const incoming =
  $input.first().json ?? {};

const body =
  incoming.body &&
  typeof incoming.body === 'object' &&
  !Array.isArray(incoming.body)
    ? incoming.body
    : incoming;

function requiredString(
  value,
  fieldName
) {
  const normalized =
    String(value ?? '').trim();

  if (!normalized) {
    throw new Error(
      `Missing ${fieldName}`
    );
  }

  return normalized;
}

function optionalString(value) {
  const normalized =
    String(value ?? '').trim();

  return normalized || null;
}

function requiredPositiveInteger(
  value,
  fieldName
) {
  const number =
    Number(value);

  if (
    !Number.isInteger(number) ||
    number <= 0
  ) {
    throw new Error(
      `Missing or invalid ${fieldName}`
    );
  }

  return number;
}

function optionalPositiveInteger(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number =
    Number(value);

  return (
    Number.isInteger(number) &&
    number > 0
  )
    ? number
    : null;
}

function objectValue(value) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed =
        JSON.parse(value);

      return (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      )
        ? parsed
        : {};
    } catch {
      return {};
    }
  }

  return {};
}

function arrayValue(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed =
        JSON.parse(value);

      return Array.isArray(parsed)
        ? parsed
        : [];
    } catch {
      return [];
    }
  }

  return [];
}

const sessionId =
  requiredString(
    body.session_id,
    'session_id'
  );

const usecaseId =
  requiredPositiveInteger(
    body.usecase_id,
    'usecase_id'
  );

const message =
  requiredString(
    body.message,
    'message'
  );

const usecaseName =
  optionalString(
    body.usecase_name
  );

const userId =
  optionalPositiveInteger(
    body.user_id
  );

const userMappingId =
  optionalPositiveInteger(
    body.user_mapping_id
  );

const userUsecaseId =
  optionalPositiveInteger(
    body.user_usecase_id
  );

/*
 * Distinguish an intentional All Users scope
 * from an accidentally missing user ID.
 */
const allUsersSelected =
  body.all_users_selected === true ||
  String(
    body.all_users_selected ?? ''
  )
    .trim()
    .toLowerCase() === 'true';

const requestedScope =
  String(
    body.analysis_scope ?? ''
  )
    .trim()
    .toLowerCase();

const analysisScope =
  requestedScope === 'participant' ||
  requestedScope === 'usecase'
    ? requestedScope
    : allUsersSelected
      ? 'usecase'
      : 'participant';

const context =
  objectValue(
    body.context
  );

const openArtifacts =
  arrayValue(
    body.open_artifacts
  );

return [{
  json: {
    session_id:
      sessionId,

    message,

    usecase_id:
      usecaseId,

    usecase_name:
      usecaseName,

    user_id:
      userId,

    user_name:
      optionalString(
        body.user_name
      ),

    user_mapping_id:
      userMappingId,

    user_usecase_id:
      userUsecaseId,

    user_usecase_name:
      optionalString(
        body.user_usecase_name
      ),

    all_users_selected:
      allUsersSelected,

    analysis_scope:
      analysisScope,

    context,

    open_artifacts:
      openArtifacts,

    app_context: {
      selected_usecase_id:
        usecaseId,

      selected_usecase_name:
        usecaseName,

      selected_user_id:
        userId,

      selected_user_name:
        optionalString(
          body.user_name
        ),

      selected_user_mapping_id:
        userMappingId,

      selected_user_usecase_id:
        userUsecaseId,

      selected_user_usecase_name:
        optionalString(
          body.user_usecase_name
        ),

      all_users_selected:
        allUsersSelected,

      analysis_scope:
        analysisScope
    }
  }
}];

const ctx =
  $input.first().json ?? {};

const input =
  $('Validate input')
    .first()
    .json ?? {};

function parseArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return [];
  }

  if (typeof value === 'string') {
    try {
      const parsed =
        JSON.parse(value);

      return Array.isArray(parsed)
        ? parsed
        : [];
    } catch {
      return [];
    }
  }

  return [];
}

function parseObject(value) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed =
        JSON.parse(value);

      return (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      )
        ? parsed
        : {};
    } catch {
      return {};
    }
  }

  return {};
}

const message =
  input.message ?? '';

const sessionId =
  input.session_id ?? null;

const selectedUserId =
  input.user_id ?? null;

const selectedUserName =
  input.user_name ?? null;

const selectedUserMappingId =
  input.user_mapping_id ?? null;

const selectedUserUsecaseId =
  input.user_usecase_id ?? null;

const selectedUserUsecaseName =
  input.user_usecase_name ?? null;

const appContext =
  parseObject(
    input.app_context
  );

const additionalContext =
  parseObject(
    input.context
  );

const openArtifacts =
  parseArray(
    input.open_artifacts
  );

const history =
  parseArray(
    ctx.conversation_history
  );

const globalMappings =
  parseArray(
    ctx.global_mappings
  );

const plannerSchema = {
  intent:
    'mapping | knowledge | dictionary | scheduling | usecase_builder | clarify',

  action:
    '',

  target_workflow:
    'mapping_manager | expert_panel | dictionary_manager | schedule_manager | use_case_builder | clarify',

  read_only:
    true,

  requires_confirmation:
    false,

  reply:
    '',

  payload: {
    action:
      '',

    params:
      {}
  }
};

const systemPrompt = `
You are the planning and routing layer of a research assistant embedded in a haptic-feedback research application.

Your task is to interpret the researcher's message and choose exactly one target workflow.

You do not execute database operations yourself.

IMPORTANT SYSTEM RULE

Release 1 supports one active mapping per user globally.

Do not claim that the system supports a separate active mapping for every user/use-case combination unless the database and runtime are changed together.

TARGET WORKFLOWS

1. mapping_manager

Use this for deterministic feedback-mapping operations:

- list active mappings;
- list all mappings;
- add a mapping;
- remove a mapping;
- change a global mapping;
- duplicate and change a mapping only for a specific participant;
- assign an existing mapping to a participant;

2. expert_panel

Use this for every read-only knowledge, explanation, analysis, research, or recommendation request.

Examples:

- explain one current mapping;
- explain a vibration parameter;
- explain the selected use case;
- explain the purpose or architecture of the project;
- answer literature or research questions;
- compare mapping approaches;
- analyze participant data;
- assess participant-specific adaptation;
- discuss personalization strategies;
- analyze feedback burden;
- analyze safety considerations;
- provide evidence, citations, trade-offs, or recommendations;
- combine project context, literature, mapping design, or participant data.
- suggest an brainstorm new mappings based on user data

The expert panel is read-only.

It must never be used to perform a database mutation.

For a simple question, the expert panel may call only one relevant expert.

For a broad question, it may call several experts.

3. dictionary_manager

Use this for deterministic UseCaseDictionary operations:

- list dictionary entries;
- retrieve a use case's parameters;
- add a parameter;
- edit a parameter;
- remove a parameter;
- remove a use case's dictionary entries.

4. schedule_manager

Use this for deterministic schedule operations:

- add a schedule;
- change a schedule;
- activate a schedule;
- deactivate a schedule;
- list active schedules;
- list all schedules.

5. use_case_builder

Use this when the researcher asks for implementation instructions or generated template configuration for adding an external API-based use case.

6. clarify

Use this when required information is missing or the request is ambiguous.

OUTPUT CONTRACT

Return only one valid JSON object matching this structure:

${JSON.stringify(
  plannerSchema,
  null,
  2
)}

GENERAL ROUTING RULES

- Never return text outside the JSON object.
- Never invent numeric IDs.
- Preserve explicit IDs supplied by the researcher or selected application context.
- Do not route a read-only question to a mutation workflow.
- Do not route an explicit mutation request to the expert panel.
- Every read-only knowledge, explanation, analysis, comparison, research, evidence, or recommendation request must use expert_panel.
- There is no separate knowledge_agent workflow.
- If the researcher explicitly asks not to change anything, read_only must be true.
- If a request is ambiguous, choose clarify instead of guessing.
- requires_confirmation should normally be false in the current release.
- For an ambiguous mutation, use clarify rather than setting requires_confirmation to true.

MAPPING RULES

For mapping operations:

- intent must be mapping.
- target_workflow must be mapping_manager.
- payload.action must contain the Mapping Manager action.
- action must match payload.action.

Supported mapping actions:

- list
- listAll
- add
- remove
- change
- duplicate_mapping_for_user
- assign
- brainstorm

Mapping list:

{
  "intent": "mapping",
  "action": "list",
  "target_workflow": "mapping_manager",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "list",
    "params": {}
  }
}

Mapping listAll:

{
  "intent": "mapping",
  "action": "listAll",
  "target_workflow": "mapping_manager",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "listAll",
    "params": {}
  }
}

Mapping add:

{
  "intent": "mapping",
  "action": "add",
  "target_workflow": "mapping_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "add",
    "params": {
      "minvalue": 80,
      "maxvalue": 100,
      "minpulses": 3,
      "maxpulses": 5,
      "minintensity": 60,
      "maxintensity": 80,
      "minduration": 200,
      "maxduration": 300,
      "mininterval": 100,
      "maxinterval": 150
    }
  }
}

Adding a new range is always add, even when a similar range may already exist.

Mapping remove:

{
  "intent": "mapping",
  "action": "remove",
  "target_workflow": "mapping_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "remove",
    "params": {
      "id": 123
    }
  }
}

Removal requires an explicit numeric mapping ID.

Mapping global change:

{
  "intent": "mapping",
  "action": "change",
  "target_workflow": "mapping_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "change",
    "params": {
      "id": 123,
      "minpulses": 3
    }
  }
}

Use change only for a global update affecting all participants assigned to the mapping.

Mapping participant-only change:

{
  "intent": "mapping",
  "action": "duplicate_mapping_for_user",
  "target_workflow": "mapping_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "duplicate_mapping_for_user",
    "params": {
      "id": 123,
      "user_id": 456,
      "minpulses": 3
    }
  }
}

Always use duplicate_mapping_for_user when the researcher explicitly asks to change a mapping only for one participant.

Include only fields explicitly requested for change. Mapping Manager copies unchanged fields.

Mapping assignment:

{
  "intent": "mapping",
  "action": "assign",
  "target_workflow": "mapping_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "assign",
    "params": {
      "id": 123,
      "user_id": 456
    }
  }
}

Use assign when an existing mapping should be assigned without changing its values.

Mapping brainstorm:

{
  "intent": "mapping",
  "action": "brainstorm",
  "target_workflow": "mapping_manager",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "brainstorm",
    "params": {}
  }
}

Use brainstorm only for basic mapping suggestions that the Mapping Manager can handle directly.

Use expert_panel instead when the request asks for evidence, literature, participant data, safety, burden, comparison, trade-offs, or multi-expert analysis.

When the researcher says "that mapping", "this mapping", or "the selected mapping":

- use selected_user_mapping_id when it exists;
- if the immediately previous assistant reply listed or discussed more than one mapping ID, use clarify unless the researcher supplies an explicit mapping ID;
- when it does not exist and exactly one active mapping exists, use that mapping's ID;
- otherwise use clarify.

When the researcher targets a specific participant:

- use the explicit participant ID when provided;
- otherwise use selected_user_id when available;
- otherwise use clarify.

If a global mapping is shared by multiple participants and the researcher asks to modify it without saying whether the change is global or participant-only, use clarify.

EXPERT PANEL RULES

All knowledge requests use this structure:

{
  "intent": "knowledge",
  "action": "analyze",
  "target_workflow": "expert_panel",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "analyze",
    "params": {}
  }
}

Use expert_panel for both simple explanations and broad analysis.

The expert panel decides internally which expert or experts are needed.

Never send a mutation request to expert_panel.

DICTIONARY RULES

Supported actions:

- list
- add
- remove_usecase
- remove_parameter
- edit
- get

Dictionary list:

{
  "intent": "dictionary",
  "action": "list",
  "target_workflow": "dictionary_manager",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "list",
    "params": {}
  }
}

Dictionary get:

{
  "intent": "dictionary",
  "action": "get",
  "target_workflow": "dictionary_manager",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "get",
    "params": {
      "usecase_name": ""
    }
  }
}

Dictionary add example:

{
  "intent": "dictionary",
  "action": "add",
  "target_workflow": "dictionary_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "add",
    "params": {
      "usecase_name": "",
      "parameter_name": "",
      "parameter_value": ""
    }
  }
}

Dictionary edit example:

{
  "intent": "dictionary",
  "action": "edit",
  "target_workflow": "dictionary_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "edit",
    "params": {
      "usecase_name": "",
      "parameter_name": "",
      "parameter_value": ""
    }
  }
}

Dictionary remove parameter example:

{
  "intent": "dictionary",
  "action": "remove_parameter",
  "target_workflow": "dictionary_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "remove_parameter",
    "params": {
      "usecase_name": "",
      "parameter_name": ""
    }
  }
}

Dictionary remove use case example:

{
  "intent": "dictionary",
  "action": "remove_usecase",
  "target_workflow": "dictionary_manager",
  "read_only": false,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "remove_usecase",
    "params": {
      "usecase_name": ""
    }
  }
}

SCHEDULING RULES

Supported actions:

- add
- change
- deactivate
- activate
- listActive
- listAll

Schedule list active:

{
  "intent": "scheduling",
  "action": "listActive",
  "target_workflow": "schedule_manager",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "listActive",
    "params": {}
  }
}

Schedule list all:

{
  "intent": "scheduling",
  "action": "listAll",
  "target_workflow": "schedule_manager",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "listAll",
    "params": {}
  }
}

Schedule add, change, deactivate, and activate are not read-only.

USE CASE BUILDER RULES

Use this structure:

{
  "intent": "usecase_builder",
  "action": "generate_template_code",
  "target_workflow": "use_case_builder",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "",
  "payload": {
    "action": "generate_template_code",
    "params": {
      "usecase_name": "",
      "api_name": "",
      "api_id": null,
      "measurement_name": "",
      "response_value_path": "",
      "endpoint_url": "",
      "context": ""
    }
  }
}

When a use-case or API name is supplied, copy it into usecase_name and api_name unless the researcher clearly gives different names.

When a measured value is supplied, copy it into measurement_name.

When a JSON response path is supplied, copy it into response_value_path.

Leave missing string values empty and missing api_id as null.

CLARIFY RULES

- Use clarify when:
  - a required mapping ID is missing;
  - a required participant ID is missing;
  - a mutation target is ambiguous;
  - the researcher refers to a mapping that cannot be identified safely;
  - the desired workflow cannot be selected reliably;
  - the researcher asks an off-topic or general knowledge question (e.g., history, math, trivia) unrelated to the haptic research system.

For clarify:
{
  "intent": "clarify",
  "action": "clarify",
  "target_workflow": "clarify",
  "read_only": true,
  "requires_confirmation": false,
  "reply": "I can only assist with questions related to the smartwatch haptic research system, experiment data, literature, and mapping configurations. Please ask a research-related question.",
  "payload": {
    "action": "clarify",
    "params": {}
  }
}

CURRENT EXPERIMENT

Use-case ID:
${ctx.usecase_id ?? input.usecase_id ?? 'unknown'}

Use-case name:
${ctx.usecase_name ?? input.usecase_name ?? 'unknown'}

Use-case description:
${ctx.usecase_description ?? 'No description available'}

ACTIVE FEEDBACK MAPPINGS

${JSON.stringify(globalMappings)}

SELECTED APPLICATION CONTEXT

${JSON.stringify({
  selected_user_id:
    selectedUserId,

  selected_user_name:
    selectedUserName,

  selected_user_mapping_id:
    selectedUserMappingId,

  selected_user_usecase_id:
    selectedUserUsecaseId,

  selected_user_usecase_name:
    selectedUserUsecaseName
}, null, 2)}

ADDITIONAL REQUEST CONTEXT

${JSON.stringify(additionalContext)}

OPEN ARTIFACTS PROVIDED BY THE APP

${JSON.stringify(openArtifacts)}
`;

const messages = [
  {
    role:
      'system',

    content:
      systemPrompt
  },

  {
    role:
      'user',

    content:
      message
  }
];

const messagesAsText =
  messages
    .map(item => {
      const role =
        item.role === 'system'
          ? 'SYSTEM'
          : item.role === 'assistant'
            ? 'ASSISTANT'
            : 'USER';

      return `${role}: ${item.content}`;
    })
    .join(
      String.fromCharCode(
        10,
        10
      )
    );

return [{
  json: {
    session_id:
      sessionId,

    message,

    messages,

    messages_as_text:
      messagesAsText,

    system_prompt:
      systemPrompt,

    usecase_id:
      ctx.usecase_id ??
      input.usecase_id ??
      null,

    usecase_name:
      ctx.usecase_name ??
      input.usecase_name ??
      null,

    global_mappings:
      globalMappings,

    history,

    selected_user_id:
      selectedUserId,

    selected_user_name:
      selectedUserName,

    selected_user_mapping_id:
      selectedUserMappingId,

    selected_user_usecase_id:
      selectedUserUsecaseId,

    selected_user_usecase_name:
      selectedUserUsecaseName,

    app_context:
      appContext,

    context:
      additionalContext,

    open_artifacts:
      openArtifacts
  }
}];

const input =
  $input.first().json ?? {};

const buildPrompt =
  $('Build prompt')
    .first()
    .json ?? {};

function isObject(value) {
  return (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function objectValue(value) {
  if (isObject(value)) {
    return value;
  }

  return {};
}

function booleanValue(
  value,
  fallback
) {
  if (
    value === true ||
    value === false
  ) {
    return value;
  }

  if (typeof value === 'string') {
    const normalized =
      value
        .trim()
        .toLowerCase();

    if (normalized === 'true') {
      return true;
    }

    if (normalized === 'false') {
      return false;
    }
  }

  return fallback;
}

function parseModelOutput(value) {
  if (isObject(value)) {
    return value;
  }

  let text =
    String(value ?? '')
      .trim();

  text = text
    .replace(
      /^```json\s*/i,
      ''
    )
    .replace(
      /^```\s*/i,
      ''
    )
    .replace(
      /\s*```$/i,
      ''
    )
    .trim();

  try {
    return JSON.parse(text);
  } catch {
    const firstBrace =
      text.indexOf('{');

    const lastBrace =
      text.lastIndexOf('}');

    if (
      firstBrace >= 0 &&
      lastBrace > firstBrace
    ) {
      try {
        return JSON.parse(
          text.slice(
            firstBrace,
            lastBrace + 1
          )
        );
      } catch {
        return {};
      }
    }

    return {};
  }
}

const candidate =
  input.text ??
  input.output ??
  input.response ??
  input.result ??
  input.answer ??
  input;

const parsed =
  parseModelOutput(
    candidate
  );

const validIntents =
  new Set([
    'mapping',
    'knowledge',
    'dictionary',
    'scheduling',
    'usecase_builder',
    'clarify'
  ]);

const validTargets =
  new Set([
    'mapping_manager',
    'expert_panel',
    'dictionary_manager',
    'schedule_manager',
    'use_case_builder',
    'clarify'
  ]);

let intent =
  String(
    parsed.intent ?? ''
  ).trim();

if (
  !validIntents.has(intent)
) {
  intent =
    'clarify';
}

const defaultTargetByIntent = {
  mapping:
    'mapping_manager',

  knowledge:
    'expert_panel',

  dictionary:
    'dictionary_manager',

  scheduling:
    'schedule_manager',

  usecase_builder:
    'use_case_builder',

  clarify:
    'clarify'
};

let targetWorkflow =
  String(
    parsed.target_workflow ?? ''
  ).trim();

if (
  !validTargets.has(
    targetWorkflow
  )
) {
  targetWorkflow =
    defaultTargetByIntent[
      intent
    ];
}

/*
 * Force every semantic intent to its permitted workflow.
 *
 * This prevents the model from returning an unsupported or
 * disconnected workflow.
 */
if (
  intent === 'mapping'
) {
  targetWorkflow =
    'mapping_manager';
}

if (
  intent === 'knowledge'
) {
  targetWorkflow =
    'expert_panel';
}

if (
  intent === 'dictionary'
) {
  targetWorkflow =
    'dictionary_manager';
}

if (
  intent === 'scheduling'
) {
  targetWorkflow =
    'schedule_manager';
}

if (
  intent ===
  'usecase_builder'
) {
  targetWorkflow =
    'use_case_builder';
}

if (
  intent === 'clarify'
) {
  targetWorkflow =
    'clarify';
}

const rawPayload =
  objectValue(
    parsed.payload
  );

const rawParams =
  objectValue(
    rawPayload.params
  );

let action =
  String(
    parsed.action ??
    rawPayload.action ??
    ''
  ).trim();

/*
 * All knowledge requests use the GraphRAG Expert Panel.
 */
if (
  intent === 'knowledge'
) {
  action =
    'analyze';
}

if (
  intent === 'clarify'
) {
  action =
    'clarify';
}

const payload = {
  action,

  params:
    rawParams
};

function arrayValue(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  return [];
}

function stringValue(value) {
  return String(value ?? '').trim();
}

function recentConversationItems() {
  const context = objectValue(buildPrompt.context);
  const sessionMemory = objectValue(context.session_memory);

  const combined = [
    ...arrayValue(buildPrompt.history),
    ...arrayValue(context.recent_conversation),
    ...arrayValue(sessionMemory.recent_conversation)
  ];

  return combined
    .filter(item => isObject(item))
    .map(item => ({
      role: stringValue(item.role).toLowerCase(),
      content: stringValue(item.content)
    }))
    .filter(item => item.role && item.content);
}

function latestConversationContent(role) {
  const requestedRole = stringValue(role).toLowerCase();
  const items = recentConversationItems();

  for (let index = items.length - 1; index >= 0; index--) {
    if (items[index].role === requestedRole) {
      return items[index].content;
    }
  }

  const context = objectValue(buildPrompt.context);
  const sessionMemory = objectValue(context.session_memory);

  if (requestedRole === 'user') {
    return stringValue(sessionMemory.previous_user_request);
  }

  if (requestedRole === 'assistant') {
    return stringValue(sessionMemory.previous_assistant_reply);
  }

  return '';
}

function mappingIdsFromText(text) {
  const ids = new Set();
  const source = stringValue(text);
  const patterns = [
    /\bID\s+(\d+)\b/gi,
    /\bmapping\s*(?:ID\s*)?(\d+)\b/gi,
    /\bmapping_id\s*[:=]?\s*(\d+)\b/gi
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(source)) !== null) {
      ids.add(Number(match[1]));
    }
  }

  return [...ids].filter(Number.isFinite);
}

function currentMessageHasExplicitMappingId(text) {
  const source = stringValue(text);
  return /\bmapping\s*(?:ID\s*)?\d+\b/i.test(source) ||
    /\bID\s+\d+\b/i.test(source) ||
    /\bmapping_id\s*[:=]?\s*\d+\b/i.test(source);
}

function asksAboutPreviousRequest(text) {
  const source = stringValue(text).toLowerCase();
  return /\bwhat\s+did\s+i\s+(just\s+)?ask\b/.test(source) ||
    /\bwhat\s+did\s+i\s+ask\s+about\s+earlier\b/.test(source) ||
    /\bwhat\s+was\s+my\s+(last|previous)\s+(question|request)\b/.test(source) ||
    /\bremind\s+me\s+what\s+i\s+(just\s+)?asked\b/.test(source);
}

function isMappingPronounMutation(text) {
  const source = stringValue(text).toLowerCase();
  const refersToMapping = /\b(that|this|selected)\s+mapping\b/.test(source);
  const mutates = /\b(change|update|modify|edit|remove|delete|deactivate|assign|set)\b/.test(source);
  return refersToMapping && mutates;
}

function forceClarifyWithReply(message) {
  intent = 'clarify';
  targetWorkflow = 'clarify';
  action = 'clarify';
  payload.action = 'clarify';
  payload.params = {};
  readOnly = true;
  requiresConfirmation = false;
  reply = message;
}

const readOnlyMappingActions =
  new Set([
    'list',
    'listAll',
    'brainstorm'
  ]);

const readOnlyDictionaryActions =
  new Set([
    'list',
    'get'
  ]);

const readOnlyScheduleActions =
  new Set([
    'listActive',
    'listAll'
  ]);

let readOnly =
  booleanValue(
    parsed.read_only,
    true
  );

/*
 * Read-only workflow guarantees.
 */
if (
  targetWorkflow ===
    'expert_panel' ||
  targetWorkflow ===
    'use_case_builder' ||
  targetWorkflow ===
    'clarify'
) {
  readOnly =
    true;
}

if (
  targetWorkflow ===
    'mapping_manager'
) {
  readOnly =
    readOnlyMappingActions.has(
      action
    );
}

if (
  targetWorkflow ===
    'dictionary_manager'
) {
  readOnly =
    readOnlyDictionaryActions.has(
      action
    );
}

if (
  targetWorkflow ===
    'schedule_manager'
) {
  readOnly =
    readOnlyScheduleActions.has(
      action
    );
}

let requiresConfirmation =
  booleanValue(
    parsed.requires_confirmation,
    false
  );

let reply =
  String(
    parsed.reply ?? ''
  ).trim();

const currentMessage =
  stringValue(buildPrompt.message);

if (asksAboutPreviousRequest(currentMessage)) {
  const previousUserRequest =
    latestConversationContent('user');

  const previousAssistantReply =
    latestConversationContent('assistant');

  if (previousUserRequest) {
    const assistantContext = previousAssistantReply
      ? ` The assistant response was about: ${previousAssistantReply}`
      : '';

    forceClarifyWithReply(
      `You just asked: "${previousUserRequest}".` + assistantContext
    );
  } else {
    forceClarifyWithReply(
      'I do not have an earlier user request in this use-case session yet.'
    );
  }
} else if (
  isMappingPronounMutation(currentMessage) &&
  !currentMessageHasExplicitMappingId(currentMessage)
) {
  const previousAssistantReply =
    latestConversationContent('assistant');

  const previousMappingIds =
    mappingIdsFromText(previousAssistantReply);

  if (previousMappingIds.length > 1) {
    forceClarifyWithReply(
      `Which mapping ID do you want to change? I can see multiple mapping IDs from the previous response: ${previousMappingIds.join(', ')}.`
    );
  }
}

/*
 * The current release does not use a separate confirmation
 * workflow. Convert model-generated confirmation requests into
 * clarification.
 */
if (
  requiresConfirmation
) {
  intent =
    'clarify';

  targetWorkflow =
    'clarify';

  action =
    'clarify';

  payload.action =
    'clarify';

  payload.params =
    {};

  readOnly =
    true;

  requiresConfirmation =
    false;

  if (!reply) {
    reply =
      'Please clarify the exact change you want to make before I continue.';
  }
}

if (
  targetWorkflow ===
    'clarify' &&
  !reply
) {
  reply =
    'Could you clarify what you would like me to do?';
}

/*
 * Correct missing actions after workflow validation.
 */
if (
  targetWorkflow ===
    'expert_panel'
) {
  intent =
    'knowledge';

  action =
    'analyze';

  payload.action =
    'analyze';

  readOnly =
    true;
}

if (
  targetWorkflow ===
    'clarify'
) {
  intent =
    'clarify';

  action =
    'clarify';

  payload.action =
    'clarify';

  readOnly =
    true;
}

return [{
  json: {
    intent,

    action,

    target_workflow:
      targetWorkflow,

    read_only:
      readOnly,

    requires_confirmation:
      requiresConfirmation,

    reply,

    payload,

    session_id:
      buildPrompt.session_id ??
      null,

    message:
      buildPrompt.message ??
      '',

    history:
      buildPrompt.history ??
      [],

    usecase_id:
      buildPrompt.usecase_id ??
      null,

    usecase_name:
      buildPrompt.usecase_name ??
      null,

    global_mappings:
      buildPrompt.global_mappings ??
      [],

    selected_user_id:
      buildPrompt.selected_user_id ??
      null,

    selected_user_name:
      buildPrompt.selected_user_name ??
      null,

    selected_user_mapping_id:
      buildPrompt.selected_user_mapping_id ??
      null,

    selected_user_usecase_id:
      buildPrompt.selected_user_usecase_id ??
      null,

    selected_user_usecase_name:
      buildPrompt.selected_user_usecase_name ??
      null,

    app_context:
      buildPrompt.app_context ??
      {},

    context:
      buildPrompt.context ??
      {},

    open_artifacts:
      buildPrompt.open_artifacts ??
      []
  }
}];

const input =
  $input.first().json ?? {};

const route =
  $('Parse GPT Response')
    .first()
    .json ?? {};

function copyWhenPresent(
  target,
  source,
  field
) {
  if (
    source[field] !== undefined
  ) {
    target[field] =
      source[field];
  }
}

function firstText(...values) {
  for (const value of values) {
    if (
      value !== null &&
      value !== undefined &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

const reply =
  firstText(
    input.reply,
    input.output,
    input.text,
    input.answer,
    input.response,
    input.result,
    route.reply
  );

const output = {
  reply,

  session_id:
    input.session_id ??
    route.session_id ??
    null,

  intent:
    route.intent ??
    null,

  target_workflow:
    route.target_workflow ??
    null,

  read_only:
    route.read_only ??
    true,

  requires_confirmation:
    route.requires_confirmation ??
    false
};

const additiveFields = [
  'success',
  'expert',
  'citations',
  'warnings',
  'proposals',
  'recommended_actions',
  'findings',
  'dictionaryEntries',
  'participant_assessment',
  'mapping_assessment',
  'workflow_assessment',
  'affected_components',
  'safety_assessment',
  'burden_assessment',
  'affected_parameters'
];

for (
  const field of
  additiveFields
) {
  copyWhenPresent(
    output,
    input,
    field
  );
}

return [{
  json:
    output
}];

